  "components": {
    "securitySchemes": {
      "BearerAuth": {
        "type": "http",
        "scheme": "bearer",
        "bearerFormat": "JWT"
      }
    },
    "schemas": {
      "SampleInput": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "sample_code": {
            "type": "string",
            "pattern": "^[A-Za-z0-9_.-]+$",
            "maxLength": 120
          },
          "age_at_scan_weeks": {
            "type": "number",
            "minimum": 20,
            "maximum": 80,
            "nullable": true
          },
          "birth_age_weeks": {
            "type": "number",
            "minimum": 20,
            "maximum": 45,
            "nullable": true
          },
          "sex": {
            "type": "string",
            "enum": [
              "Female",
              "Male",
              "Unknown"
            ]
          },
          "has_dmri": {
            "type": "boolean"
          },
          "has_fmri": {
            "type": "boolean"
          },
          "status": {
            "type": "string",
            "enum": [
              "registered",
              "ready",
              "processing",
              "completed",
              "failed"
            ]
          },
          "visibility": {
            "type": "string",
            "enum": [
              "private",
              "shared"
            ]
          },
          "description": {
            "type": "string",
            "maxLength": 2000
          }
        }
      },
      "NoteInput": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "text": {
            "type": "string",
            "minLength": 1,
            "maxLength": 4000
          },
          "category": {
            "type": "string",
            "enum": [
              "research",
              "quality",
              "review"
            ]
          }
        }
      },
      "AnalysisInput": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "modality": {
            "type": "string",
            "enum": [
              "dmri",
              "fmri",
              "combined"
            ]
          },
          "estimated_age_weeks": {
            "type": "number",
            "minimum": 20,
            "maximum": 80
          },
          "method": {
            "type": "string",
            "minLength": 1,
            "maxLength": 120
          },
          "model_version": {
            "type": "string",
            "minLength": 1,
            "maxLength": 120
          },
          "provenance": {
            "type": "string",
            "minLength": 1,
            "maxLength": 1000
          },
          "quality_score": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "nullable": true
          }
        }
      },
      "Login": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "username",
          "password"
        ],
        "properties": {
          "username": {
            "type": "string"
          },
          "password": {
            "type": "string",
            "format": "password"
          }
        }
      },
      "Register": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "username",
          "password",
          "display_name"
        ],
        "properties": {
          "username": {
            "type": "string"
          },
          "password": {
            "type": "string",
            "format": "password"
          },
          "display_name": {
            "type": "string"
          }
        }
      },
      "PasswordChange": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "current_password",
          "new_password"
        ],
        "properties": {
          "current_password": {
            "type": "string",
            "format": "password"
          },
          "new_password": {
            "type": "string",
            "format": "password"
          }
        }
      },
      "UserUpdate": {
        "type": "object",
        "additionalProperties": false,
        "minProperties": 1,
        "properties": {
          "active": {
            "type": "boolean"
          },
          "role": {
            "type": "string",
            "enum": [
              "admin",
              "researcher"
            ]
          }
        }
      },
      "Error": {
        "type": "object",
        "properties": {
          "error": {
            "type": "object",
            "properties": {
              "status": {
                "type": "integer"
              },
              "message": {
                "type": "string"
              }
            }
          }
        }
      }
    }
  }
